///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 조회 버튼 클릭 — 기본정보 서식매핑 목록 조회(scwin.search)를 실행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Search_onclick(e);
 */
scwin.btn_Search_onclick = function(e) {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description 목록 조회 완료 콜백 — 총 서식수·총 엘리먼트수를 패널 메시지 영역에 표시한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadCompleted(e);
 */
scwin.dts_List_OnLoadCompleted = function(e) {
    try {
        scwin.PanelMsg(panel_msg, "총 서식수: " + dts_List.getCellData(1, "FORM_CD_TOTAL_CNT") + ",  총 엘리먼트수: " + $c.num.formatNumber(rowcount));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description 목록 조회 실패 콜백 — 서브미션 오류 메시지를 표시한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.dts_List_OnLoadError(e);
 */
scwin.dts_List_OnLoadError = function(e) {
    try {
        $c.win.alert + $c.data.getMessage(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description 저장 실패 콜백 — 서브미션 오류 메시지를 표시한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.trs_Save_OnFail(e);
 */
scwin.trs_Save_OnFail = function(e) {
    try {
        $c.win.alert + $c.data.getMessage(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description 저장 성공 콜백 — 목록을 재조회한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.trs_Save_OnSuccess(e);
 */
scwin.trs_Save_OnSuccess = function(e) {
    try {
        // alert("저장 성공");
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 엑셀다운로드 버튼 클릭 — 화면 처리 로그 저장 후 그리드(grd_Grid)를 엑셀 파일로 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_Excel_onclick(e);
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        doLogSave('ULDSTF95010.gfm', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "기본정보맵핑항목", type: 8}); // 16
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_FORM_CD_onkeypress
 * @description 서식코드 입력란 키 입력 — Enter(13) 입력 시 조회를 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.txb_FORM_CD_onkeypress();
 */
scwin.txb_FORM_CD_onkeypress = function() {
    try {
        if (event.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.txb_FORM_CD_onkeypress" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 그리드 행 더블클릭 — 엘리먼트명(ELMT_KOR_NM) 컬럼이면 해당 서식의 양식보기 팝업을 연다.
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_Grid_OnDblClick(row, colid);
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        if (colid === "ELMT_KOR_NM") {

            scwin.openForm(dts_List.getCellData(row, "FORM_CD"), dts_List.getCellData(row, "FORM_VER"), dts_List.getCellData(row, "FORM_X_PATH"), dts_List.getCellData(row, "ELMT_KOR_NM"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_ELMT_KOR_NM_onclick
 * @description 엘리먼트명 입력란 이벤트 — Enter(13) 입력 시 조회를 실행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_ELMT_KOR_NM_onclick(e);
 */
scwin.txb_ELMT_KOR_NM_onclick = function(e) {
    try {
        if (event.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT50002.txb_ELMT_KOR_NM_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 조회조건(시장구분·서식코드/버전·대표버전여부·엘리먼트명)으로 URL 파라미터를 구성해 sbm_dts_List 동적 서브미션으로 목록을 조회하고 완료 후 구 콜백(dts_List_OnLoadCompleted)을 연결한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example await scwin.search();
 */
scwin.search = async function() {
    const vMKT_ID = getObjectValue(rdo_MKT_ID);
    const vFORM_CD = getObjectValue(txb_FORM_CD);
    const vFORM_VER = getObjectValue(txb_FORM_VER);
    const vREP_FORM_VER_YN = getObjectValue(rdo_REP_FORM_VER_YN);
    url += "&LD_MKT_TP_CD=" + vMKT_ID;
    url += "&FORM_CD=" + vFORM_CD;
    url += "&FORM_VER=" + vFORM_VER;
    url += "&REP_FORM_VER_YN=" + vREP_FORM_VER_YN;
    url += "&ELMT_KOR_NM=" + getObjectValue(txb_ELMT_KOR_NM);
    url += "&SCREN_ID=" + 'ULDSTF95010.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.PanelMsg(panel_msg, "로딩중....기다려주세요.");
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/kclic.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name PanelMsg
 * @description 패널 영역에 안내 메시지 HTML(테이블 레이아웃)을 렌더링한다.
 * @param {Object} panelID 메시지를 표시할 패널 요소
 * @param {String} msg 표시할 메시지
 * @returns {void}
 * @hidden N
 * @example scwin.PanelMsg(panel_msg, "메시지");
 */
scwin.PanelMsg = function(panelID, msg) {
    const vTotalArea = "<span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + msg + "</span>";
    panelID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};

/**
 * @method
 * @name save
 * @description 저장 처리(현재 미구현 스텁).
 * @returns {void}
 * @hidden N
 * @example scwin.save();
 */
scwin.save = function() {

};

/**
 * @method
 * @name openForm
 * @description 엘리먼트명을 4자리 HEX 인코딩한 XPATH 파라미터로 서식 양식보기 팝업 창을 연다.
 * @param {String} form_cd 서식코드
 * @param {String} form_ver 서식버전
 * @param {String} x_path 서식 XPATH
 * @param {String} elmt_kor_nm 엘리먼트명
 * @returns {void}
 * @hidden N
 * @example scwin.openForm("A0001", "1", xPath, "회사명");
 */
scwin.openForm = function(form_cd, form_ver, x_path, elmt_kor_nm) {
    // 서식별로 모든항목들에 대해서 보여주려 했으나 팝업호출시 문자열이 길어 호출시 에러발생. 건별로 양식보기에서 보여준다.
    // var form_x_path = getFormXPath(form_cd,x_path); 
    const form_x_path = scwin.StringToHex4(elmt_kor_nm) + ":" + x_path;
    let url = "/filing/findForm.do?method=scheduleFormView";
    url += "&formCd=" + form_cd;
    url += "&formVer=" + form_ver;
    url += "&form_x_path=" + form_x_path;

    window.open(url, "", "scrollbars=yes,toolbar=no,resizable=yes,width=850,height=700,left=0,top=0");
};

/**
 * @method
 * @name StringToHex4
 * @description 문자열의 각 문자를 4자리 16진수 문자코드로 변환해 이어붙인 대문자 문자열을 반환한다.
 * @param {String} OriginalString 변환할 원본 문자열
 * @returns {String}
 * @hidden N
 * @example const hex = scwin.StringToHex4("회사명");
 */
scwin.StringToHex4 = function(OriginalString) {
    let ReturnString = "";
    for (let i = 0; i < OriginalString.length; i++) {
        const tmp = "0000" + (parseInt(OriginalString.charCodeAt(i)).toString(16));
        const tmp2 = tmp.substring(tmp.length - 4);
        ReturnString += tmp2;
    }
    return ReturnString.toUpperCase();
};

/**
 * @method
 * @name getFormXPath
 * @description 목록(dts_List)에서 지정 서식코드의 엘리먼트명:XPATH 쌍을 콤마로 연결한 문자열을 생성한다.
 * @param {String} form_cd 서식코드
 * @param {String} x_path 서식 XPATH(현재 미사용)
 * @returns {String}
 * @hidden N
 * @example const path = scwin.getFormXPath("A0001", xPath);
 */
scwin.getFormXPath = function(form_cd, x_path) {
    let str = "";
    for (let i = 0; i < dts_List.getRowCount(); i++) {
        if (form_cd === dts_List.getCellData(i, "FORM_CD")) {
            if (i === 0) {
                str += dts_List.getCellData(i, "ELMT_KOR_NM");
                str += ":" + dts_List.getCellData(i, "X_PATH");
            } else {
                str += "," + dts_List.getCellData(i, "ELMT_KOR_NM");
                str += ":" + dts_List.getCellData(i, "X_PATH");
            }
        }
    }
    return str;
};

/**
 * @method
